.workspace-header h1 { margin:0; color:var(--ink); font-size:28px; line-height:1.2; font-weight:760; letter-spacing:-.9px; text-wrap:balance; overflow-wrap:anywhere; }
.workspace-state { display:flex; flex-direction:column; align-items:center; justify-content:center; padding:48px 24px; min-height:260px; margin:16px 0; border:1px solid var(--line); border-radius:16px; background:var(--card); text-align:center; }
.workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) { border-radius:14px; border:1px solid var(--line); background:var(--card); padding:5px; gap:4px; margin-bottom:20px; }
.workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) button { min-width:0; min-height:54px; padding:10px 12px; border:0; border-radius:10px; background:transparent; box-shadow:none; color:var(--muted); }
.workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) button.active { background:var(--brand-soft); color:var(--brand); }
.workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) small { color:var(--muted); font-size:12px; line-height:1.4; }
.workspace-view :is(.feature-toolbar,.feature-search,.social-settings,.settings-card,.feature-preferences) { border-color:var(--line); }
.workspace-view :is(.feature-dialog,.pulse-dialog,.social-dialog,.library-live-dialog) input { accent-color:var(--brand-solid,var(--brand)); }
.workspace-view :is(.profile-content-panel,.workspace-state) { min-width:0; }
@media (max-width:780px) {
  .workspace-state,.workspace-view.notes-workspace .workspace-state { min-height:240px; padding:32px 20px; }
  .workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) { overflow:visible; }
  .workspace-view :is(.pulse-tabs,.campus-guide-tabs) { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) button { padding:10px 9px; }
  .workspace-view :is(.pulse-tabs,.social-tabs,.market-tabs,.campus-guide-tabs) small { font-size:12px; line-height:1.4; white-space:normal; overflow:visible; text-overflow:clip; }
}

* { box-sizing: border-box; }
button, input, textarea { font: inherit; }
button { color: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }

@media (max-width: 780px) {
}
.notes-source-switch { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; margin:0 0 18px; }
.notes-source-switch button { min-width:0; padding:14px 16px; border:1px solid var(--line); border-radius:14px; background:var(--card); color:var(--ink); text-align:left; cursor:pointer; }
.notes-source-switch button[aria-pressed="true"] { border-color:var(--brand); box-shadow:inset 0 0 0 1px var(--brand); background:var(--brand-soft); }
.notes-source-switch strong,.notes-source-switch span { display:block; }
.notes-source-switch strong { font-size:.9375rem; }
.notes-source-switch span { margin-top:4px; color:var(--muted); font-size:.8125rem; line-height:1.4; }
.notes-workspace .notes-toolbar { flex-wrap:wrap; padding:4px 14px 14px; border:1px solid var(--line); border-radius:14px; background:var(--card); }
.notes-toolbar>div { min-height:42px; overflow-x:auto; max-width:100%; }
.notes-toolbar>div button { flex-shrink:0; }
.notes-toolbar select { min-height:40px; max-width:min(320px,75vw); }
.notes-pagination button,.notes-empty-actions button { min-height:42px; padding:8px 12px; border:1px solid var(--line); border-radius:10px; background:var(--card); color:var(--ink); font-weight:650; cursor:pointer; }
.notes-pagination button:disabled { opacity:.4; cursor:default; }
.notes-filter-controls { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; width:100%; }
.notes-filter-controls label { display:flex; align-items:center; gap:8px; min-width:0; color:var(--muted); font-size:.8125rem; }
.notes-workspace .notes-filter-controls select { min-width:0; width:100%; max-width:100%; min-height:44px; }
@media (max-width:780px) {
  .notes-workspace .workspace-header h1 { font-size:22px; }
  .notes-source-switch { margin-bottom:12px; }
  .notes-source-switch button { padding:12px; min-height:48px; }
  .notes-source-switch span { display:none; }
  .notes-workspace .notes-toolbar { gap:10px; margin-top:0; margin-bottom:10px; padding:4px 10px 10px; }
  .notes-workspace .notes-toolbar>div { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:4px 8px; overflow:visible; border-bottom:0; }
  .notes-workspace .notes-toolbar>div button { min-height:40px; border-radius:8px; }
  .notes-workspace .notes-toolbar>div button.active { background:var(--brand-soft); }
  .notes-workspace .notes-toolbar>div button.active::after { display:none; }
  .notes-workspace .notes-filter-controls { gap:8px; }
  .notes-filter-controls label { flex-direction:column; align-items:stretch; gap:4px; }
  .notes-workspace .notes-filter-controls select { max-width:100%; font-size:16px; }
  .notes-workspace .workspace-state { min-height:0; padding:22px 16px; }
}
.curated-library-header { margin-bottom:13px; padding:17px 18px; display:flex; align-items:center; justify-content:space-between; gap:18px; border:1px solid #dcd8ff; border-radius:18px; background:linear-gradient(135deg,#faf9ff,#f1efff); }
.curated-note-card { min-width:0; min-height:218px; display:flex; flex-direction:column; overflow:hidden; border:1px solid #e1dff0; border-radius:17px; background:#fff; box-shadow:0 10px 28px rgba(42,37,91,.045); content-visibility:auto; contain-intrinsic-size:218px; }
.curated-note-main h3 { margin:7px 0 6px; color:var(--ink); font-size:1rem; line-height:1.35; letter-spacing:-.15px; transition:color .15s ease; }
.curated-note-main p { margin:0; color:#666b7e; font-size:.9375rem; line-height:1.52; }
.curated-detail-intro { margin:17px 20px 0; padding:16px; border:1px solid #dcd8ff; border-radius:15px; background:#f8f7ff; }
.curated-detail-intro p { margin:10px 0 7px; color:#4e5468; font-size:1rem; line-height:1.62; }
.curated-detail-columns { margin:16px 20px; display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.curated-sources { margin:0 20px 18px; padding:15px; border:1px solid #e4e3eb; border-radius:15px; background:#fafafa; }
.curated-sources>a { min-height:54px; margin-top:7px; padding:9px 10px; display:flex; align-items:center; justify-content:space-between; gap:12px; border:1px solid #e3e2eb; border-radius:11px; background:#fff; color:inherit; text-decoration:none; }

@media (max-width: 780px) {
  .curated-library-header { align-items:flex-start; padding:15px; }.curated-note-card{min-height:0}.curated-note-main p{font-size:.9375rem}
  .curated-detail-intro,.curated-detail-columns,.curated-sources,.curated-detail>footer { margin-left:16px; margin-right:16px; }
  .curated-detail-columns { grid-template-columns:1fr; }
}
.feature-toolbar { min-height:55px; margin:12px 0 16px; display:flex; align-items:center; justify-content:space-between; gap:14px; border-bottom:1px solid #e8e8ef; }
.feature-toolbar>div { display:flex; align-self:stretch; gap:20px; }
.feature-toolbar>div { scrollbar-width:none; }
.feature-toolbar>div button { position:relative; border:0; background:transparent; color:#868a9d; font:inherit; font-size:.875rem; font-weight:690; cursor:pointer; }
.feature-toolbar>div button.active { color:var(--ink); }
.feature-toolbar>div button.active::after { content:""; position:absolute; height:2px; inset:auto 0 -1px; border-radius:99px; background:var(--brand); }
.feature-toolbar select { max-width:220px; border:1px solid #e1e1e9; border-radius:9px; padding:7px 9px; background:#fff; color:#5f6477; font:inherit; font-size:.8125rem; }
.feature-dialog input,.feature-dialog select,.feature-dialog textarea { width:100%; border:1px solid #dcdae6; border-radius:11px; padding:10px 11px; outline:0; background:#fff; color:var(--ink); font:inherit; font-size:1rem; line-height:1.45; }
.feature-dialog textarea { resize:vertical; }

@media (max-width: 780px) {
  .feature-toolbar { align-items:flex-start; flex-direction:column; padding-bottom:11px; border-bottom:0; }.feature-toolbar>div{width:100%;min-height:46px;border-bottom:1px solid #e8e8ef;overflow:auto}.feature-toolbar select{max-width:70%}
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior:auto!important; transition-duration:.01ms!important; animation-duration:.01ms!important; animation-iteration-count:1!important; }
}
.campus-guide-tabs { padding:6px; display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:7px; border:1px solid #e5e3ef; border-radius:16px; background:#efeff5; }
.campus-guide-tabs button { min-width:0; min-height:63px; padding:9px 13px; display:flex; flex-direction:column; align-items:flex-start; justify-content:center; gap:3px; border:1px solid transparent; border-radius:11px; background:transparent; color:#777b8e; font:inherit; cursor:pointer; }
.campus-guide-tabs button.active { border-color:#e0dcff; background:#fff; color:#30287f; box-shadow:0 6px 16px rgba(27,25,74,.07); }
.campus-guide-tabs small { color:#9396a5; font-size:.6875rem; }
.campus-guide-empty { margin-top:16px; min-height:250px; padding:28px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; border:1px dashed #d9d6e8; border-radius:18px; background:#fbfbfd; }
