.campus-guide-empty button { min-height:39px; padding:0 13px; border:0; border-radius:10px; background:var(--brand); color:#fff; font:inherit; font-size:.8125rem; font-weight:720; cursor:pointer; }
.campus-guide-layout { margin-top:12px; display:grid; grid-template-columns:minmax(0,1.1fr) minmax(270px,.9fr); gap:12px; align-items:start; }
.campus-place-list article { min-width:0; overflow:hidden; padding:15px; border:1px solid #e4e2ec; border-radius:15px; background:#fff; cursor:pointer; }
.campus-place-list article.active { border-color:#bfb8ff; box-shadow:0 0 0 3px rgba(91,77,240,.07); }
.campus-place-list h2 { margin:4px 0 0; overflow-wrap:anywhere; color:#292d45; font-size:.875rem; }
.campus-place-list article>p { margin:10px 0 6px; color:#55596e; font-size:.75rem; line-height:1.55; }
.campus-map-panel { position:sticky; top:24px; overflow:hidden; border:1px solid #e2e0eb; border-radius:17px; background:#fff; box-shadow:0 10px 30px rgba(31,28,73,.05); }
.campus-event-list article { padding:15px; display:grid; grid-template-columns:auto minmax(0,1fr) auto; align-items:start; gap:13px; border:1px solid #e3e1eb; border-radius:16px; background:#fff; }
.daily-suggestion { margin-top:16px; min-height:390px; padding:36px; display:flex; flex-direction:column; align-items:center; justify-content:center; border:1px solid #ded9ff; border-radius:22px; background:radial-gradient(circle at 50% 0,#ebe8ff,transparent 45%),linear-gradient(145deg,#fff,#f8f7ff); text-align:center; }.daily-suggestion h2 { margin:7px 0; color:#242742; font-size:1.5rem; }
.daily-suggestion>p { max-width:520px; margin:0; color:#6c7084; font-size:.875rem; line-height:1.6; }.daily-suggestion>button { min-height:40px; margin-top:18px; padding:0 14px; border:0; border-radius:10px; background:#2e2b6b; color:#fff; font:inherit; font-size:.75rem; font-weight:720; cursor:pointer; }
.campus-guide-dialog input,.campus-guide-dialog select,.campus-guide-dialog textarea { width:100%; border:1px solid #dedce8; border-radius:10px; background:#fbfbfd; color:#252940; font:inherit; font-size:.8125rem; outline:none; }
.campus-guide-dialog input,.campus-guide-dialog select { min-height:43px; padding:0 11px; }.campus-guide-dialog textarea { padding:11px; resize:vertical; line-height:1.55; }.campus-form-row { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
.exam-filter-strip{margin:-4px 0 17px;padding:13px 14px;display:flex;align-items:center;gap:12px;border:1px solid #dedaff;border-radius:14px;background:linear-gradient(135deg,#f8f7ff,#fff)}.exam-upload-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.exam-upload-fields label{display:grid;gap:6px;color:#555a70;font-size:.75rem;font-weight:720}.exam-upload-fields input,.exam-upload-fields select{width:100%;min-height:43px;padding:0 11px;border:1px solid #dedce8;border-radius:10px;background:#fbfbfd;color:#252940;font:inherit;font-size:.8125rem}.exam-upload-warning{margin:0;padding:11px;border:1px solid #eee0bd;border-radius:10px;background:#fffaf0;color:#7f6b47;font-size:.6875rem;line-height:1.5}
.campus-guide-tabs{grid-template-columns:repeat(4,minmax(0,1fr))}

@media (max-width: 780px) {
  .campus-guide-tabs { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .campus-guide-tabs button { min-height:53px; }
  .campus-guide-layout { grid-template-columns:1fr; }
  .campus-map-panel { position:static; order:-1; }
  .campus-event-list article { grid-template-columns:auto minmax(0,1fr); }
  .campus-form-row { grid-template-columns:1fr; }
  .daily-suggestion { min-height:350px; padding:25px 18px; }
  .exam-filter-strip{align-items:stretch;flex-wrap:wrap}.exam-upload-fields{grid-template-columns:1fr}
